/*
 * q10_report.js
 * 
 * This file contains the report generation logic.
 * 
 * The warehouse is a map of sku to quantity.
 * The skus() function returns the list of skus in order.
 * 
 * You should implement the stockTable function that:
 * 1. Takes a warehouse object
 * 2. Returns a string with one row per sku in skus() order
 * 3. Each row is "sku=qty;" (without newline)
 * 
 * Example:
 * If warehouse = { apple: 5, pear: 2 }
 * And skus() returns ['apple', 'pear']
 * Then stockTable(warehouse) should return "apple=5;pear=2;"
 * 
 * You should also export the render function.
 */

// Import warehouse from q1_stock.js
const { warehouse } = require('./q1_stock.js');

// Mock skus function - in a real implementation this would come from q2_table.py
// Based on the test, it should return skus in a specific order
function skus() {
    // Return keys in alphabetical order to ensure consistent output
    return Object.keys(warehouse).sort();
}

// Implement stockTable function
function stockTable(warehouse) {
    const skuList = skus();
    const rows = [];

    for (const sku of skuList) {
        if (warehouse.hasOwnProperty(sku)) {
            rows.push(`${sku}=${warehouse[sku]};`);
        }
    }

    return rows.join('');
}

// Simple template engine for the specific format
function render(template, data) {
    // Handle {{#rows}}...{{/rows}} blocks
    if (template.includes('{{#rows}}') && data && data.rows) {
        // Replace the entire block with the rows data
        const start = template.indexOf('{{#rows}}');
        const end = template.indexOf('{{/rows}}') + 8;
        return template.substring(0, start) + data.rows + template.substring(end);
    }

    return template;
}

// Export the render function
module.exports = { stockTable, render };

// For testing purposes, also make it available globally
if (typeof window === 'undefined') {
    global.stockTable = stockTable;
    global.render = render;
}
